INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_math_u1_L02_basic#1','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X14']::text[],true,'{"seq":1,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 3","correct":true},{"t":"3 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 3","mis":"M6-1-u1-X14"},{"t":"2 + 3","mis":"M6-1-u1-X14"}],"explanation":["전체 2개를 3으로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 3이 뒤에 와요.","그래서 식은 2 ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 ÷ 4","correct":true},{"t":"4 ÷ 3","mis":"M6-1-u1-X14"},{"t":"3 × 4","mis":"M6-1-u1-X14"},{"t":"3 + 4","mis":"M6-1-u1-X14"}],"explanation":["전체 3개를 4로 똑같이 나누는 거예요.","나누어지는 수 3이 앞, 나누는 수 4가 뒤에 와요.","그래서 식은 3 ÷ 4예요."]},{"stem":"흰 종이 2장을 5명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 흰 종이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 ÷ 5","correct":true},{"t":"5 ÷ 2","mis":"M6-1-u1-X14"},{"t":"2 × 5","mis":"M6-1-u1-X14"},{"t":"2 + 5","mis":"M6-1-u1-X14"}],"explanation":["전체 2장을 5로 똑같이 나누는 거예요.","나누어지는 수 2가 앞, 나누는 수 5가 뒤에 와요.","그래서 식은 2 ÷ 5예요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#2','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'mc','auto','시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":2,"concept":"M6-1-u1-C2","difficulty":1,"kind":"mc","stem":"시루떡 1개를 4명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 시루떡은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"4","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["시루떡 1개를 4로 똑같이 나누는 것은 1 ÷ 4예요.","나누어지는 수 1은 분자, 나누는 수 4는 분모가 돼요.","1 ÷ 4 = ⟨1/4⟩ — ⟨1/4⟩개예요."],"variant_rule":{"alt":[{"stem":"식빵 1개를 6명이 똑같이 나누어 먹으려고 해요. 한 명이 먹는 식빵은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"6","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X09"},{"t":"1","mis":"M6-1-u1-X01"}],"explanation":["식빵 1개를 6으로 똑같이 나누는 것은 1 ÷ 6이에요.","나누어지는 수 1은 분자, 나누는 수 6은 분모가 돼요.","1 ÷ 6 = ⟨1/6⟩ — ⟨1/6⟩개예요."]},{"stem":"과자 반죽 2개를 3명이 똑같이 나누어 가지려고 해요. 한 명이 가지는 과자 반죽은 몇 개인지 분수로 나타내면 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨2/5⟩","mis":"M6-1-u1-X09"}],"explanation":["과자 반죽 2개를 3으로 똑같이 나누는 것은 2 ÷ 3이에요.","나누어지는 수 2는 분자, 나누는 수 3은 분모가 돼요.","2 ÷ 3 = ⟨2/3⟩ — ⟨2/3⟩개예요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#3','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',1,'sa','auto','3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u1-C2","difficulty":1,"kind":"sa","stem":"3 ÷ 5의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 3은 분자, 나누는 수 5는 분모예요.","3 ÷ 5 = ⟨3/5⟩이니 분자는 3이에요."],"mis":"M6-1-u1-X01","variant_rule":{"alt":[{"stem":"2 ÷ 7의 몫을 분수로 나타낼 때 분모에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 2는 분자, 나누는 수 7은 분모예요.","2 ÷ 7 = ⟨2/7⟩니 분모는 7이에요."]},{"stem":"4 ÷ 9의 몫을 분수로 나타낼 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["(자연수)÷(자연수)의 몫은 분수로 나타낼 수 있어요.","나누어지는 수 4는 분자, 나누는 수 9는 분모예요.","4 ÷ 9 = ⟨4/9⟩니 분자는 4예요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#4','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',1,'mc','auto','⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X12']::text[],true,'{"seq":4,"concept":"M6-1-u1-C1","difficulty":1,"kind":"mc","stem":"⟨9/36⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨4/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/5⟩","mis":"M6-1-u1-X12"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","9와 36의 최대공약수는 9예요.","9 ÷ 9 = 1, 36 ÷ 9 = 4라 ⟨9/36⟩ = ⟨1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨12/18⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/2⟩","mis":"M6-1-u1-X12"},{"t":"1","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","12와 18의 최대공약수는 6이에요.","12 ÷ 6 = 2, 18 ÷ 6 = 3이라 ⟨12/18⟩ = ⟨2/3⟩예요."]},{"stem":"⟨15/45⟩를 약분하여 가장 간단한 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨3/1⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/4⟩","mis":"M6-1-u1-X12"},{"t":"⟨2/3⟩","mis":"M6-1-u1-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","15와 45의 최대공약수는 15예요.","15 ÷ 15 = 1, 45 ÷ 15 = 3이라 ⟨15/45⟩ = ⟨1/3⟩이에요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#5','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'mc','auto','2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u1-X02','M6-1-u1-X14']::text[],true,'{"seq":5,"concept":"M6-1-u1-C1","difficulty":2,"kind":"mc","stem":"2 ÷ 3은 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 2로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 3으로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["2 ÷ 3을 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 2도 3으로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨2/3⟩처럼 분수로 적을 수 있어요."],"variant_rule":{"alt":[{"stem":"3 ÷ 5는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 0, 나머지 3로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 5로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["3 ÷ 5를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 3도 5로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨3/5⟩처럼 분수로 적을 수 있어요."]},{"stem":"5 ÷ 4는 나누어떨어지지 않아요. 이 나눗셈의 몫을 나타내는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남은 것도 똑같이 나누어 몫을 분수로 적는다","correct":true},{"t":"나눌 수 없다고 적는다","mis":"M6-1-u1-X02"},{"t":"몫 1, 나머지 1로만 적고 끝낸다","mis":"M6-1-u1-X02"},{"t":"나누어지는 수를 4로 바꾸어 나눈다","mis":"M6-1-u1-X14"}],"explanation":["5 ÷ 4를 몫과 나머지로만 두면 한 사람이 실제로 얼마를 가지는지 알 수 없어요.","남은 1도 4로 똑같이 나누어 줄 수 있어요.","그러면 몫을 ⟨1 1/4⟩처럼 분수로 적을 수 있어요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#6','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C1',2,'sa','auto','과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u1-C1","difficulty":2,"kind":"sa","stem":"과자 반죽 2개를 3명이 나누려고 과자 반죽을 하나씩 모두 3조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["과자 반죽 하나를 3조각으로 잘라요.","과자 반죽 2개 모두 자르면 2 × 3 = 6조각이에요.","그래서 조각은 모두 6개예요."],"mis":"M6-1-u1-X15","variant_rule":{"alt":[{"stem":"시루떡 3개를 4명이 나누려고 시루떡을 하나씩 모두 4조각으로 잘랐어요. 한 명이 가지는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["조각은 모두 3 × 4 = 12개예요.","12조각을 4명이 똑같이 나누면 12 ÷ 4 = 3조각씩이에요.","한 조각이 ⟨1/4⟩이니 한 명 몫은 ⟨3/4⟩이에요."]},{"stem":"피자 2판을 5명이 나누려고 피자를 하나씩 모두 5조각으로 잘랐어요. 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["피자 하나를 5조각으로 잘라요.","피자 2판 모두 자르면 2 × 5 = 10조각이에요.","그래서 조각은 모두 10개예요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#7','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?',ARRAY['M6-1-u1-X01','M6-1-u1-X09']::text[],true,'{"seq":7,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"3 ÷ 8의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨2 2/3⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/8⟩","mis":"M6-1-u1-X01"},{"t":"⟨3/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 8 = ⟨1/8⟩ — 1을 8로 나눈 한 조각이에요.","3 ÷ 8은 그 조각이 3개예요.","3 ÷ 8 = ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"5 ÷ 9의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 4/5⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/9⟩","mis":"M6-1-u1-X01"},{"t":"⟨5/14⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 9 = ⟨1/9⟩ — 1을 9로 나눈 한 조각이에요.","5 ÷ 9는 그 조각이 5개예요.","5 ÷ 9 = ⟨5/9⟩예요."]},{"stem":"4 ÷ 7의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨1 3/4⟩","mis":"M6-1-u1-X01"},{"t":"⟨1/7⟩","mis":"M6-1-u1-X01"},{"t":"⟨4/11⟩","mis":"M6-1-u1-X09"}],"explanation":["1 ÷ 7 = ⟨1/7⟩ — 1을 7로 나눈 한 조각이에요.","4 ÷ 7은 그 조각이 4개예요.","4 ÷ 7 = ⟨4/7⟩예요."]}]}}'::jsonb),
('g6_1_math_u1_L02_basic#8','math',6,1,'u1','L02','g6_1_math_u1_L02_basic','lesson_basic','M6-1-u1-C2',2,'mc','auto','몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u1-X03']::text[],true,'{"seq":8,"concept":"M6-1-u1-C2","difficulty":2,"kind":"mc","stem":"몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"5 ÷ 8","correct":true},{"t":"3 ÷ 3","mis":"M6-1-u1-X03"},{"t":"9 ÷ 7","mis":"M6-1-u1-X03"},{"t":"11 ÷ 4","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","5 ÷ 8 = ⟨5/8⟩, 3 ÷ 3 = 1, 9 ÷ 7 = ⟨1 2/7⟩, 11 ÷ 4 = ⟨2 3/4⟩이에요.","그래서 몫이 1보다 작은 것은 5 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4 ÷ 9","correct":true},{"t":"7 ÷ 6","mis":"M6-1-u1-X03"},{"t":"5 ÷ 5","mis":"M6-1-u1-X03"},{"t":"8 ÷ 3","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","7 ÷ 6 = ⟨1 1/6⟩, 4 ÷ 9 = ⟨4/9⟩, 5 ÷ 5 = 1, 8 ÷ 3 = ⟨2 2/3⟩예요.","그래서 몫이 1보다 작은 것은 4 ÷ 9예요."]},{"stem":"이번에는 다른 보기예요. 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2 ÷ 11","correct":true},{"t":"6 ÷ 6","mis":"M6-1-u1-X03"},{"t":"10 ÷ 9","mis":"M6-1-u1-X03"},{"t":"13 ÷ 5","mis":"M6-1-u1-X03"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작고, 크면 1보다 커요.","6 ÷ 6 = 1, 10 ÷ 9 = ⟨1 1/9⟩, 2 ÷ 11 = ⟨2/11⟩, 13 ÷ 5 = ⟨2 3/5⟩이에요.","그래서 몫이 1보다 작은 것은 2 ÷ 11이에요."]}]}}'::jsonb),
