('g6_1_math_u1_review_c#8','math',6,1,'u1','','g6_1_math_u1_review_c','unit_review','M6-1-u1-C7',1,'mc','auto','저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?',ARRAY['M6-1-u1-X13']::text[],true,'{"seq":8,"concept":"M6-1-u1-C7","difficulty":1,"kind":"mc","stem":"저울에서 파란 뚜껑 3개와 노란 뚜껑 1개의 무게가 파란 뚜껑 6개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"},{"t":"4개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 3개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 6 − 3 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."],"variant_rule":{"alt":[{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 7개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"},{"t":"9개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 7 − 2 = 5개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 5개와 같아요."]},{"stem":"저울에서 파란 뚜껑 2개와 노란 뚜껑 1개의 무게가 파란 뚜껑 5개의 무게와 같아요(같은 색 뚜껑은 무게가 같아요). 노란 뚜껑 1개는 파란 뚜껑 몇 개와 무게가 같나요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M6-1-u1-X13"},{"t":"5개","mis":"M6-1-u1-X13"},{"t":"7개","mis":"M6-1-u1-X13"}],"explanation":["양쪽에서 파란 뚜껑 2개씩을 덜어 내도 저울은 수평이에요.","왼쪽엔 노란 뚜껑 1개, 오른쪽엔 파란 뚜껑 5 − 2 = 3개가 남아요.","그래서 노란 뚜껑 1개는 파란 뚜껑 3개와 같아요."]}]}}'::jsonb),
