('g6_1_math_u2_L04_basic#4','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'sa','auto','삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C3","difficulty":1,"kind":"sa","stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 직사각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]},{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 면은 모두 몇 개 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]}]}}'::jsonb),
('g6_1_math_u2_L04_basic#5','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'sa','auto','사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C3","difficulty":2,"kind":"sa","stem":"사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 4개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["8"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 6개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"오각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["7"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 5개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb),
('g6_1_math_u2_L04_basic#6','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":6,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"길이가 항상 같아요","correct":true},{"t":"길이가 항상 달라요","mis":"M6-1-u2-X09"},{"t":"긴 쪽이 밑면이 돼요","mis":"M6-1-u2-X09"},{"t":"길이는 상관없어요","mis":"M6-1-u2-X09"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."],"variant_rule":{"alt":[{"stem":"전개도의 양쪽 끝에 있는 두 선분은 접었을 때 어떻게 되나요?","options":[{"t":"서로 맞닿아 하나의 모서리가 돼요","correct":true},{"t":"서로 떨어져 있어요","mis":"M6-1-u2-X07"},{"t":"밑면이 돼요","mis":"M6-1-u2-X01"},{"t":"잘라서 버려요","mis":"M6-1-u2-X07"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]},{"stem":"전개도에서 맞닿는 두 선분의 길이가 다르면 어떻게 되나요?","options":[{"t":"접었을 때 틈이 생기거나 남는 곳이 생겨요","correct":true},{"t":"그대로 각기둥이 돼요","mis":"M6-1-u2-X09"},{"t":"각뿔이 돼요","mis":"M6-1-u2-X11"},{"t":"면의 수가 늘어나요","mis":"M6-1-u2-X08"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]}]}}'::jsonb),
('g6_1_math_u2_L04_basic#7','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'ox','auto','전개도에서 잘린 모서리는 점선으로 나타내요.',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"mis":"M6-1-u2-X07","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","answer":"O","reason_options":[{"t":"밑면의 변 하나마다 옆면이 하나씩 세워지기 때문에","correct":true},{"t":"옆면은 언제나 4개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"면들이 서로 떨어져 있는 그림도 전개도예요.","answer":"X","reason_options":[{"t":"전개도는 모든 면이 이어지도록 펼친 그림이기 때문에","correct":true},{"t":"면의 수만 맞으면 되기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb),
