('g6_1_math_u2_L04_challenge#2','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',2,'ox','auto','전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":2,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.","answer":"O","reason_options":[{"t":"두 선분이 맞닿아 하나의 모서리가 되기 때문에","correct":true},{"t":"긴 선분이 짧은 선분을 덮기 때문에","mis":"M6-1-u2-X09"}],"mis":"M6-1-u2-X09","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 6개 그려져요.","answer":"X","reason_options":[{"t":"밑면 2개와 옆면 6개 — 면이 8개 그려지기 때문에","correct":true},{"t":"육각기둥이니 면도 6개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"전개도에는 밑면이 1개만 그려져 있어도 돼요.","answer":"X","reason_options":[{"t":"각기둥은 밑면이 2개라 전개도에도 2개가 있어야 하기 때문에","correct":true},{"t":"접으면 밑면이 저절로 생기기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb),
