('g6_1_math_u2_L07_basic#4','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',1,'mc','auto','각뿔의 꼭짓점은 어떤 점인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X10']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"각뿔의 꼭짓점은 어떤 점인가요?","options":[{"t":"옆면이 모두 만나는 점","correct":true},{"t":"밑면의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"모서리의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"밑면의 꼭짓점","mis":"M6-1-u2-X10"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"각뿔의 높이는 무엇인가요?","options":[{"t":"각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이","correct":true},{"t":"옆 모서리의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 가장 긴 변의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]},{"stem":"각뿔에서 옆 모서리의 길이가 높이가 될 수 없는 까닭은 무엇인가요?","options":[{"t":"옆 모서리는 비스듬히 기울어져 높이보다 길기 때문에","correct":true},{"t":"옆 모서리는 밑면에 있기 때문에","mis":"M6-1-u2-X05"},{"t":"옆 모서리는 높이보다 짧기 때문에","mis":"M6-1-u2-X06"},{"t":"각뿔에는 높이가 없기 때문에","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]}]}}'::jsonb),
('g6_1_math_u2_L07_basic#5','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'sa','auto','육각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"육각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 13 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 12 cm예요."]},{"stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."]}]}}'::jsonb),
('g6_1_math_u2_L07_basic#6','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'ox','auto','오각뿔의 꼭짓점은 5개예요.',ARRAY['M6-1-u2-X10']::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":2,"kind":"ox","stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"mis":"M6-1-u2-X10","explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."],"variant_rule":{"alt":[{"stem":"옆면이 4개인 각뿔은 사각뿔이에요.","answer":"O","reason_options":[{"t":"옆면의 수는 밑면의 변의 수와 같아 밑면이 사각형이기 때문에","correct":true},{"t":"각뿔의 이름은 면의 수로 정하기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]},{"stem":"각뿔의 옆 모서리의 길이가 각뿔의 높이예요.","answer":"X","reason_options":[{"t":"높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이이기 때문에","correct":true},{"t":"옆 모서리가 가장 길기 때문에","mis":"M6-1-u2-X06"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]}]}}'::jsonb),
('g6_1_math_u2_L07_basic#7','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'sa','auto','팔각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"팔각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["칠각뿔의 밑면은 칠각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요."]},{"stem":"구각뿔의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","면을 세는 방법을 떠올려요.","밑면 1개와 옆면 9개 — 9 + 1 = 10개예요."]}]}}'::jsonb),
