('g6_1_math_u2_L08_basic#4','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',1,'sa','auto','십각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C7","difficulty":1,"kind":"sa","stem":"십각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","한 밑면의 변은 10개예요.","위 밑면 10개, 아래 밑면 10개, 옆 모서리 10개 — 10 × 3 = 30개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["11"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 10개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."]},{"stem":"십이각기둥의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 면 수 = 변의 수 + 2예요.","한 밑면의 변은 12개예요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#5','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'mc','auto','어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십이각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"십이각뿔","mis":"M6-1-u2-X11"},{"t":"십삼각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 12개가 위아래로 짝을 이뤄 — 12 × 2 = 24개예요.","한 밑면의 변이 12개라 이름은 십이각기둥이에요."],"variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 27개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X12"},{"t":"팔각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","한 밑면의 변이 9개라 이름은 구각기둥이에요."]},{"stem":"어떤 각기둥의 면이 12개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십각기둥","correct":true},{"t":"십이각기둥","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 면 수 = 변의 수 + 2예요.","밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","한 밑면의 변이 10개라 이름은 십각기둥이에요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#6','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'sa','auto','십일각뿔의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십일각뿔의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 꼭짓점 수 = 변의 수 + 1이에요.","한 밑면의 변은 11개예요.","밑면의 꼭짓점 11개와 각뿔의 꼭짓점 1개 — 11 + 1 = 12개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십오각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","한 밑면의 꼭짓점 15개가 위아래로 짝을 이뤄 — 15 × 2 = 30개예요."]},{"stem":"십삼각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["26"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 13개예요.","밑면의 변 13개와 옆 모서리 13개 — 13 × 2 = 26개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#7','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'mc','auto','각뿔에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":7,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"각뿔에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 + 1","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"}],"explanation":["삼각뿔, 사각뿔, 오각뿔의 면 수를 세어 표로 늘어놓아요.","4개, 5개, 6개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 면 수 = 변의 수 + 1이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 모서리의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 × 3","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 + 1","mis":"M6-1-u2-X12"}],"explanation":["삼각기둥, 사각기둥, 오각기둥의 모서리 수를 세어 표로 늘어놓아요.","9개, 12개, 15개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 모서리 수 = 변의 수 × 3이에요."]},{"stem":"각뿔에서 꼭짓점의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 + 1","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"}],"explanation":["삼각뿔, 사각뿔, 오각뿔의 꼭짓점 수를 세어 표로 늘어놓아요.","4개, 5개, 6개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 꼭짓점 수 = 변의 수 + 1이에요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#8','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'ox','auto','십각기둥의 모서리는 30개예요.',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":8,"concept":"M6-1-u2-C7","difficulty":2,"kind":"ox","stem":"십각기둥의 모서리는 30개예요.","answer":"O","reason_options":[{"t":"변의 수 10의 3배라 10 × 3 = 30개이기 때문에","correct":true},{"t":"십각기둥이니 10개의 3배를 빼기 때문에","mis":"M6-1-u2-X12"}],"mis":"M6-1-u2-X12","explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"십각뿔의 꼭짓점은 10개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 10개에 각뿔의 꼭짓점 1개를 더해 11개이기 때문에","correct":true},{"t":"각뿔의 꼭짓점은 세지 않기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]},{"stem":"각뿔의 모서리의 수는 언제나 짝수예요.","answer":"O","reason_options":[{"t":"모서리의 수가 변의 수의 2배이기 때문에","correct":true},{"t":"각뿔의 면이 짝수이기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#9','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 21개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 21개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 21개이니 한 밑면의 변은 7개예요.","같은 밑면의 각뿔은 칠각뿔이에요.","밑면의 변 7개와 옆 모서리 7개 — 7 × 2 = 14개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 12개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 12개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 11개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 11개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_basic#10','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',3,'match','auto','입체도형과 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u2-C7","difficulty":3,"kind":"match","stem":"입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"십각기둥","r":"면 12개"},{"l":"십각뿔","r":"모서리 20개"},{"l":"팔각기둥","r":"꼭짓점 16개"}],"mis":"M6-1-u2-X12","explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","십각기둥 면 12개, 십각뿔 모서리 20개, 팔각기둥 꼭짓점 16개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"구각뿔","r":"면 10개"},{"l":"칠각기둥","r":"모서리 21개"},{"l":"십이각뿔","r":"꼭짓점 13개"}],"explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","구각뿔 면 10개, 칠각기둥 모서리 21개, 십이각뿔 꼭짓점 13개예요."]},{"stem":"이번에는 다른 보기예요. 입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"육각기둥","r":"면 8개"},{"l":"십일각뿔","r":"모서리 22개"},{"l":"오각기둥","r":"꼭짓점 10개"}],"explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","육각기둥 면 8개, 십일각뿔 모서리 22개, 오각기둥 꼭짓점 10개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#1','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',2,'mc','auto','어떤 각뿔의 모서리가 16개예요. 이 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":1,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"어떤 각뿔의 모서리가 16개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"십육각뿔","mis":"M6-1-u2-X04"},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","한 밑면의 변이 8개라 이름은 팔각뿔이에요."],"variant_rule":{"alt":[{"stem":"어떤 각뿔의 면이 9개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X04"},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"칠각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 8개 — 8 + 1 = 9개예요.","한 밑면의 변이 8개라 이름은 팔각뿔이에요."]},{"stem":"어떤 각기둥의 꼭짓점이 28개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십사각기둥","correct":true},{"t":"십사각뿔","mis":"M6-1-u2-X11"},{"t":"십오각기둥","mis":"M6-1-u2-X12"},{"t":"십삼각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 14개가 위아래로 짝을 이뤄 — 14 × 2 = 28개예요.","한 밑면의 변이 14개라 이름은 십사각기둥이에요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#2','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',2,'sa','auto','밑면이 오각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"밑면이 오각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","차는 10 − 6 = 4개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 팔각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","차는 24 − 16 = 8개예요."]},{"stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","밑면 1개와 옆면 7개 — 7 + 1 = 8개예요.","차는 9 − 8 = 1개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#3','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'mc','auto','각기둥의 꼭짓점의 수가 한 밑면의 변의 수의 2배인 까닭은 무엇인가요?',ARRAY['M6-1-u2-X12','M6-1-u2-X10']::text[],true,'{"seq":3,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"각기둥의 꼭짓점의 수가 한 밑면의 변의 수의 2배인 까닭은 무엇인가요?","options":[{"t":"밑면이 2개라 꼭짓점이 위아래로 짝을 이루기 때문에","correct":true},{"t":"옆면이 직사각형이기 때문에","mis":"M6-1-u2-X12"},{"t":"면이 2개 더 있기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 1개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「밑면이 2개라 꼭짓점이 위아래로 짝을 이루기 때문에」예요."],"variant_rule":{"alt":[{"stem":"각뿔의 꼭짓점의 수가 한 밑면의 변의 수보다 1 큰 까닭은 무엇인가요?","options":[{"t":"밑면의 꼭짓점에 위의 한 점(각뿔의 꼭짓점)이 더해지기 때문에","correct":true},{"t":"밑면이 1개이기 때문에","mis":"M6-1-u2-X12"},{"t":"옆면이 삼각형이라 1을 더하기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 2개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「밑면의 꼭짓점에 위의 한 점(각뿔의 꼭짓점)이 더해지기 때문에」예요."]},{"stem":"각기둥의 모서리의 수가 한 밑면의 변의 수의 3배인 까닭은 무엇인가요?","options":[{"t":"위 밑면·아래 밑면·옆의 모서리가 변의 수만큼씩 세 묶음이기 때문에","correct":true},{"t":"옆면이 3개씩 있기 때문에","mis":"M6-1-u2-X12"},{"t":"꼭짓점마다 모서리가 1개씩이기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 3개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「위 밑면·아래 밑면·옆의 모서리가 변의 수만큼씩 세 묶음이기 때문에」예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#4','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'sa','auto','어떤 각뿔의 면이 10개예요. 이 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 각뿔의 면이 10개예요. 이 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["각뿔의 면 수 = 변의 수 + 1 — 한 밑면의 변은 9개예요.","이 입체도형은 구각뿔이에요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 33개예요. 이 각기둥의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각기둥이에요.","한 밑면의 꼭짓점 11개가 위아래로 짝을 이뤄 — 11 × 2 = 22개예요."]},{"stem":"어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 한 밑면의 변은 12개예요.","이 입체도형은 십이각기둥이에요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#5','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'ox','auto','각기둥의 면의 수는 언제나 꼭짓점의 수보다 많아요.',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C7","difficulty":3,"kind":"ox","stem":"각기둥의 면의 수는 언제나 꼭짓점의 수보다 많아요.","answer":"X","reason_options":[{"t":"삼각기둥만 봐도 면 5개, 꼭짓점 6개라 꼭짓점이 더 많기 때문에","correct":true},{"t":"각기둥은 면이 가장 많기 때문에","mis":"M6-1-u2-X12"}],"mis":"M6-1-u2-X12","explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"꼭짓점이 24개인 각기둥은 십이각기둥이에요.","answer":"O","reason_options":[{"t":"꼭짓점은 변의 수의 2배라 변이 12개이기 때문에","correct":true},{"t":"꼭짓점의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]},{"stem":"모서리가 16개인 각뿔은 팔각뿔이에요.","answer":"O","reason_options":[{"t":"모서리는 변의 수의 2배라 변이 8개이기 때문에","correct":true},{"t":"모서리의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#6','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'error','auto','건축가 서호가 육각기둥과 육각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X12','M6-1-u2-X14']::text[],true,'{"seq":6,"concept":"M6-1-u2-C7","difficulty":3,"kind":"error","stem":"건축가 서호가 육각기둥과 육각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「육각뿔의 모서리는 18개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"이현 — 「육각기둥의 꼭짓점은 12개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「육각뿔의 면은 7개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요.","준희는 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"건축가 서호가 팔각기둥과 팔각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「팔각뿔의 모서리는 24개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"수아 — 「팔각기둥의 꼭짓점은 16개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「팔각뿔의 면은 9개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 8개가 위아래로 짝을 이뤄 — 8 × 2 = 16개예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","서호는 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."]},{"stem":"건축가 서호가 오각기둥과 오각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「오각뿔의 모서리는 15개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"나린 — 「오각기둥의 꼭짓점은 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「오각뿔의 면은 6개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#7','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 36개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 36개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 36개이니 한 밑면의 변은 12개예요.","같은 밑면의 각뿔은 십이각뿔이에요.","밑면 1개와 옆면 12개 — 12 + 1 = 13개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 30개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 30개이니 한 밑면의 변은 15개예요.","같은 밑면의 각뿔은 십오각뿔이에요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 15개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 15개이니 한 밑면의 변은 13개예요.","같은 밑면의 각뿔은 십삼각뿔이에요.","밑면의 변 13개와 옆 모서리 13개 — 13 × 2 = 26개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#8','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'sa','auto','칠각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C7","difficulty":4,"kind":"sa","stem":"칠각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["칠각기둥의 꼭짓점은 14개, 면은 9개, 모서리는 21개예요.","14 + 9 − 21 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"구각뿔의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["구각뿔의 꼭짓점은 10개, 면은 10개, 모서리는 18개예요.","10 + 10 − 18 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."]},{"stem":"십이각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십이각기둥의 꼭짓점은 24개, 면은 14개, 모서리는 36개예요.","24 + 14 − 36 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#9','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'sa','auto','모서리 수가 50개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C7","difficulty":4,"kind":"sa","stem":"모서리 수가 50개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","변이 16개이면 48개, 17개이면 51개예요.","50개를 넘지 않으니 밑면의 변은 16개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"모서리 수가 35개를 넘지 않는 각뿔 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","변이 17개이면 34개, 18개이면 36개예요.","35개를 넘지 않으니 밑면의 변은 17개예요."]},{"stem":"꼭짓점 수가 45개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","변이 22개이면 44개, 23개이면 46개예요.","45개를 넘지 않으니 밑면의 변은 22개예요."]}]}}'::jsonb),
('g6_1_math_u2_L08_challenge#10','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'essay','teacher','각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C7","difficulty":4,"kind":"essay","stem":"각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.","answer_guide":{"answer":"예: 각기둥은 밑면이 2개라 한 밑면의 꼭짓점이 위아래로 짝을 이루므로 2배가 된다. 각뿔은 밑면이 1개이고 옆면이 모두 만나는 각뿔의 꼭짓점이 위에 한 점 더 있으므로 1을 더한다. 십각기둥의 꼭짓점은 10 × 2 = 20개, 십각뿔의 꼭짓점은 10 + 1 = 11개이다.","scoring_points":["각기둥은 밑면이 2개라 2배라고 설명했는가","각뿔은 위의 한 점을 더한다고 설명했는가","20개와 11개를 구했는가"]},"explanation":["각기둥은 위아래로 짝 — 2배예요.","각뿔은 위의 한 점 — 1을 더해요.","십각기둥 20개, 십각뿔 11개예요."]}'::jsonb),
('g6_1_math_u2_review_a#1','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',1,'mc','auto','두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."]},{"stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."]}]}}'::jsonb),
