('g6_1_math_u2_review_b#5','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',1,'sa','auto','오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["오각기둥의 밑면은 오각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."]},{"stem":"사각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["사각기둥의 밑면은 사각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#6','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',1,'sa','auto','팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 8개와 각뿔의 꼭짓점 1개 — 8 + 1 = 9개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"오각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각뿔의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."]},{"stem":"구각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#7','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도에서 실선은 무엇을 나타내나요?',ARRAY['M6-1-u2-X07','M6-1-u2-X06']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."]},{"stem":"같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?","options":[{"t":"자르는 모서리가 달라져서","correct":true},{"t":"밑면의 크기가 달라져서","mis":"M6-1-u2-X13"},{"t":"높이가 달라져서","mis":"M6-1-u2-X13"},{"t":"옆면의 수가 달라져서","mis":"M6-1-u2-X08"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#8','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',1,'sa','auto','높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 12 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 11 cm로 그려요."]},{"stem":"높이가 5 cm인 칠각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 5 cm로 그려요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#9','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',2,'mc','auto','오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."]},{"stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#10','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',2,'mc','auto','「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니기 때문에","correct":true},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「밑면이 원이고 뾰족한 점이 있는 고깔」을 이 조건에 대어 봐요.","밑면이 다각형이 아니기 때문에 각뿔이 아니에요."]},{"stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#11','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 4 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 7 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 5 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 5 cm예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#12','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',2,'sa','auto','사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 25 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."]},{"stem":"팔각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#13','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',2,'mc','auto','구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":13,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X08"},{"t":"십팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 구각형 2개가 밑면이 돼요.","직사각형 9개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 구각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."]},{"stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#14','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',2,'sa','auto','밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","3 + 4 + 5 = 12 — 가로는 12 cm예요(높이 9 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 4 cm, 5 cm, 6 cm, 7 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","4 + 5 + 6 + 7 = 22 — 가로는 22 cm예요(높이 8 cm는 세로예요)."]},{"stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 5 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","6 + 8 + 10 = 24 — 가로는 24 cm예요(높이 5 cm는 세로예요)."]}]}}'::jsonb),
('g6_1_math_u2_review_b#15','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',2,'sa','auto','십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"이십각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["40"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 20개예요.","한 밑면의 꼭짓점 20개가 위아래로 짝을 이뤄 — 20 × 2 = 40개예요."]},{"stem":"십사각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 14개예요.","밑면 1개와 옆면 14개 — 14 + 1 = 15개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#16','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',2,'ox','auto','오각뿔의 꼭짓점은 5개예요.',ARRAY['M6-1-u2-X10']::text[],true,'{"seq":16,"concept":"M6-1-u2-C6","difficulty":2,"kind":"ox","stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"mis":"M6-1-u2-X10","explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."],"variant_rule":{"alt":[{"stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#17','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'mc','auto','어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":17,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"십팔각뿔","mis":"M6-1-u2-X04"},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","한 밑면의 변이 9개라 이름은 구각뿔이에요."],"variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","한 밑면의 변이 8개라 이름은 팔각기둥이에요."]},{"stem":"어떤 각뿔의 면이 12개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"십일각뿔","correct":true},{"t":"십이각뿔","mis":"M6-1-u2-X04"},{"t":"십일각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요.","한 밑면의 변이 11개라 이름은 십일각뿔이에요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#18','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 20개이니 한 밑면의 변은 10개예요.","같은 밑면의 각뿔은 십각뿔이에요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 8개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 8개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 27개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 27개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#19','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',3,'mc','auto','「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":19,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."]},{"stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#20','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',3,'error','auto','각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X14']::text[],true,'{"seq":20,"concept":"M6-1-u2-C2","difficulty":3,"kind":"error","stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"수아 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","서호는 높이를 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「모서리가 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면이 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각뿔의 꼭짓점을 빠뜨렸어요."]},{"stem":"육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「옆면이 8개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"라온 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"예준 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","육각기둥의 옆면은 6개, 밑면은 2개예요.","여울은 면 전체의 수를 옆면의 수로 잘못 말했어요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#21','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'sa','auto','밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","차는 27 − 18 = 9개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 십각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요.","차는 12 − 11 = 1개예요."]},{"stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요.","차는 14 − 8 = 6개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#22','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":22,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 3 cm, 세로 10 cm","correct":true},{"t":"가로 10 cm, 세로 18 cm","mis":"M6-1-u2-X09"},{"t":"가로 18 cm, 세로 10 cm","mis":"M6-1-u2-X09"},{"t":"가로 3 cm, 세로 3 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 3 cm예요.","옆면의 세로는 각기둥의 높이와 같아 10 cm예요.","그래서 옆면 하나는 「가로 3 cm, 세로 10 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 6 cm인 정오각형이고 높이가 7 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 7 cm","correct":true},{"t":"가로 7 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 7 cm","mis":"M6-1-u2-X09"},{"t":"가로 6 cm, 세로 6 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 6 cm예요.","옆면의 세로는 각기둥의 높이와 같아 7 cm예요.","그래서 옆면 하나는 「가로 6 cm, 세로 7 cm」예요."]},{"stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 11 cm","correct":true},{"t":"가로 11 cm, 세로 12 cm","mis":"M6-1-u2-X09"},{"t":"가로 12 cm, 세로 11 cm","mis":"M6-1-u2-X09"},{"t":"가로 4 cm, 세로 4 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 4 cm예요.","옆면의 세로는 각기둥의 높이와 같아 11 cm예요.","그래서 옆면 하나는 「가로 4 cm, 세로 11 cm」예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#23','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',4,'sa','auto','밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u2-C6","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["밑면의 변은 5개이고 모두 3 cm예요.","옆 모서리도 5개이고 모두 9 cm예요.","5 × 3 + 5 × 9 = 60 — 모두 60 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 4 + 5 = 12 cm예요.","세로는 높이 7 cm예요.","넓이는 12 × 7 = 84 cm²예요."]},{"stem":"어떤 각뿔의 모서리가 22개예요. 이 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각뿔이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요."]}]}}'::jsonb),
('g6_1_math_u2_review_b#24','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',4,'essay','teacher','밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u2-C2","difficulty":4,"kind":"essay","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 육각기둥의 모서리는 6 × 3 = 18개이다. 두 밑면의 변 12개는 모두 3 cm이므로 12 × 3 = 36 cm이고, 옆 모서리 6개는 높이와 같은 5 cm이므로 6 × 5 = 30 cm이다. 모두 더하면 36 + 30 = 66 cm이다.","scoring_points":["밑면의 변 12개와 옆 모서리 6개로 나누었는가","36 cm와 30 cm를 구했는가","66 cm를 구했는가"]},"explanation":["밑면의 변 12개 — 12 × 3 = 36 cm예요.","옆 모서리 6개 — 6 × 5 = 30 cm예요.","36 + 30 = 66 cm예요."]}'::jsonb),
('g6_1_math_u2_review_b#25','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',4,'essay','teacher','「사각형 2개와 직사각형 4개가 이어진 그림은 언제나 사각기둥의 전개도이다.」 이 말이 맞는지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u2-C3","difficulty":4,"kind":"essay","stem":"「사각형 2개와 직사각형 4개가 이어진 그림은 언제나 사각기둥의 전개도이다.」 이 말이 맞는지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 언제나 맞는 것은 아니다. 면의 수가 맞더라도 두 사각형이 서로 합동이어야 하고, 접었을 때 맞닿는 선분의 길이가 같아야 하며, 접어서 면이 겹치지 않아야 전개도가 된다. 두 밑면이 같은 쪽에 붙어 겹치거나 길이가 맞지 않으면 사각기둥이 되지 않는다.","scoring_points":["언제나 맞는 것은 아니라고 답했는가","합동·맞닿는 선분 길이·겹침 가운데 하나 이상의 조건을 썼는가","조건이 어긋나면 사각기둥이 되지 않는다고 설명했는가"]},"explanation":["면의 수만으로는 모자라요.","밑면 합동·맞닿는 선분 길이·겹치지 않음을 봐야 해요.","그래서 언제나 맞지는 않아요."]}'::jsonb),
('g6_1_math_u2_review_c#1','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C1',1,'mc','auto','두 밑면과 만나는 면을 무엇이라고 하나요?',ARRAY['M6-1-u2-X01']::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."],"variant_rule":{"alt":[{"stem":"한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「각뿔」이에요."]},{"stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."]}]}}'::jsonb),
('g6_1_math_u2_review_c#2','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C5',1,'mc','auto','각뿔의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":2,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]},{"stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."]}]}}'::jsonb),
